/**
 * Per-repo settings of the architecture tests; the other files in this folder are
 * the same in meritum-frontend, meritum-extension and meritum-mocks.
 *
 * @feature none (infrastructure)
 */
export const settings = {
  /** Folders whose code must carry JSDoc with `@feature` and keep constants in constants.ts. */
  sourceDirs: ['src/', 'tests/'],
  /** Never checked: generated files and copies owned by other repos (path prefixes). */
  excluded: [
    'src/routeTree.gen.ts', // generated by the TanStack Router plugin
    'src/components/ui/', // shadcn components, added by the shadcn CLI
    // pnpm sync copies (scripts/sync.sh), documented and line-limited in their source
    // repo; tests/synced-copies.test.ts checks their sums:
    'src/styles/meritum.css', // design-system tokens/meritum.css
    'src/components/meritum/', // design-system components/meritum/
    'src/contracts/', // design-system contracts/ (from meritum-core) and core's catalog.json
    'src/copy/', // design-system copy/pl.json
  ],
  /** Line limit of one file. */
  maxLines: 250,
}
